#!/usr/bin/env bash
#
# mayhem/build.sh — build the nanos fuzz harnesses and the upstream host test suite.
#
# nanos is a unikernel; its runtime library (src/runtime), TFS filesystem (src/fs) and
# HTTP code (src/http) also build as ordinary Linux processes on top of
# src/unix_process (that is how upstream builds tools/{mkfs,dump} and test/unit). The
# harnesses in mayhem/fuzz link that same code; mayhem/Makefile reuses upstream's
# vars.mk/rules.mk so closure_templates.h is generated by upstream's contgen.
set -euo pipefail

[ -n "${SOURCE_DATE_EPOCH:-}" ] || unset SOURCE_DATE_EPOCH

: "${SANITIZER_FLAGS=-fsanitize=address,undefined -fno-sanitize-recover=all -fno-omit-frame-pointer}"
: "${DEBUG_FLAGS:=-g -gdwarf-3}"
: "${CC:=clang}" ; : "${CXX:=clang++}" ; : "${LIB_FUZZING_ENGINE:=-fsanitize=fuzzer}"
: "${MAYHEM_JOBS:=$(nproc)}"
: "${COVERAGE_FLAGS=}"
export SANITIZER_FLAGS DEBUG_FLAGS CC CXX LIB_FUZZING_ENGINE MAYHEM_JOBS COVERAGE_FLAGS

cd "$SRC"

# 1) Upstream host build with its NORMAL flags (gcc, as upstream's Makefiles default to):
#    tools/{mkfs,dump,contgen} and the test/unit programs that mayhem/test.sh runs.
make -j"$MAYHEM_JOBS" -C tools CC=gcc mkfs dump contgen
make -j"$MAYHEM_JOBS" -C test/unit CC=gcc all

# 2) Fuzz harnesses: the project sources and harness compiled with the sanitizers,
#    SanCov (fuzzer-no-link) and DWARF 3; linked twice — libFuzzer and the standalone
#    run-once reproducer. LeakSanitizer is disabled at build time (mayhem/lsan_off.cc).
out="$SRC/output/mayhem"
mkdir -p "$out/obj"
$CXX $SANITIZER_FLAGS $DEBUG_FLAGS -c "$SRC/mayhem/lsan_off.cc" -o "$out/obj/lsan_off.o"
$CC $SANITIZER_FLAGS $DEBUG_FLAGS -c "$STANDALONE_FUZZ_MAIN" -o "$out/obj/standalone_main.o"

# Three UBSan checks are relaxed; ASan and the rest of UBSan stay on and halting:
#  - function: nanos closures are invoked through a generic closure function-pointer
#    type by design (src/runtime/closure*.h), so every closure call trips it;
#  - null, alignment: upstream's own UBSan kernel build relaxes exactly these
#    (rules.mk: -fno-sanitize=alignment,null); `null` fires on the runtime's offsetof
#    idiom `&((T)0)->field` behind struct_from_field()/struct_from_list(). A real NULL
#    dereference still faults and ASan reports it as a SEGV;
#  - object-size: re-reports that same offsetof idiom; ASan already checks object bounds;
#  - pointer-overflow: buffer_ref() on an empty buffer (contents == NULL) computes NULL+0,
#    which happens all over the runtime for zero-length strings.
UBSAN_RELAX="-fno-sanitize=function,null,alignment,object-size,pointer-overflow"
case "$SANITIZER_FLAGS" in *undefined*) ;; *) UBSAN_RELAX="" ;; esac
FUZZ_CFLAGS="$SANITIZER_FLAGS $UBSAN_RELAX -fsanitize=fuzzer-no-link $DEBUG_FLAGS"
# make does not track flag changes: drop an object tree built with different flags
fresh_variant() {  # <variant> <flags...>
    local v="$1"; shift
    if [ "$(cat "$out/$v.flags" 2>/dev/null)" != "$*" ]; then
        rm -rf "${out:?}/$v"
        printf '%s' "$*" > "$out/$v.flags"
    fi
}
fresh_variant fuzz "$CC $FUZZ_CFLAGS $LIB_FUZZING_ENGINE"
make -j"$MAYHEM_JOBS" -C mayhem VARIANT=fuzz CC="$CC" \
    FUZZ_CFLAGS="$FUZZ_CFLAGS" FUZZ_LDFLAGS="$LIB_FUZZING_ENGINE" \
    FUZZ_EXTRA="$out/obj/lsan_off.o"

# The standalone reproducer has no libFuzzer runtime, so it is compiled without
# SanCov callbacks (a separate object tree) to link cleanly even with SANITIZER_FLAGS=''.
fresh_variant standalone "$CC $SANITIZER_FLAGS $UBSAN_RELAX $DEBUG_FLAGS"
make -j"$MAYHEM_JOBS" -C mayhem VARIANT=standalone CC="$CC" \
    FUZZ_CFLAGS="$SANITIZER_FLAGS $UBSAN_RELAX $DEBUG_FLAGS" FUZZ_LDFLAGS="" \
    FUZZ_EXTRA="$out/obj/standalone_main.o $out/obj/lsan_off.o"

for h in fuzz_tuple_parser fuzz_json fuzz_http_parser fuzz_http_listener fuzz_tfs fuzz_xml fuzz_dtb; do
    cp -f "$out/fuzz/bin/$h" "/mayhem/$h"
    cp -f "$out/standalone/bin/$h" "/mayhem/$h-standalone"
done
